let storage=true,raw=null,legacy=null;try{raw=localStorage.getItem(STORAGE_KEY);legacy=localStorage.getItem('crash-course-science-v1');}catch{storage=false;}
let state=restore(raw,legacy,lessons);let maths=null;const mathsStudio=()=>maths??=createMathsStudio({root:$('#mathsContent'),modal,closeModal:()=>{if($('#modal').open)$('#modal').close();},onProgress:({done,total,due,storage:ok,topic:mt})=>{if(state.subject==='maths'&&mt)$('.breadcrumb').textContent='Maths / '+mt;$('#sideProgress').textContent=`${done} / ${total}`;$('#progressFill').style.width=(total?done/total*100:0)+'%';$('#reviewCount').textContent=due;$('#saveStatus').textContent=ok?'Saved on this device':'Saved for this session';updateProgressBadge();}});$('#mathsContent').addEventListener('maths:subjects',()=>openSubjects());let view=state.view==='assessment'&&assessment()&&!assessment().finished?'assessment':state.view==='review'&&reviewSession()&&!reviewSession().finished?'review':'lesson';
const current=()=>{const l=lessons.find(l=>l.id===state.lessonId);return {...l,learnerTier:state.tier,learn:l.learn.filter(c=>!c.higher||state.tier==='Higher')};},available=()=>topicLessons(lessons,state.topicId,state.route,state.tier),allAvailable=()=>eligible(lessons,state.route,state.tier),topic=()=>topicById(state.topicId),subject=()=>subjects.find(s=>s.id===state.subject),qs=(l,type)=>l[type].filter(q=>state.tier==='Higher'||!l.higherQuestions?.includes(q.id));
function eligibleTopics(){return topics.filter(t=>t.subject===state.subject&&topicLessons(lessons,t.id,state.route,state.tier).length);}
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function assessment(){return contextRun(state,'assessment');}
function reviewSession(){return contextRun(state,'review');}
function progressSummary(){return state.subject==='science'?scienceSummary(lessons,topics,state,conceptNames):state.subject==='maths'&&maths?maths.getProgress():null;}
function updateProgressBadge(){const b=$('#progressButton');if(!b)return;const data=progressSummary();b.hidden=!data;if(data){$('#progressBadge').textContent=`${data.completed} / ${data.total}`;b.setAttribute('aria-label',`My progress: ${data.completed} of ${data.total} lessons completed`);}}
function openProgress(){const data=progressSummary();if(!data)return;modal(dashboardHTML(data));$$('[data-progress-lesson]').forEach(b=>b.onclick=()=>{if(state.subject==='maths'){maths.openProgressLesson(b.dataset.progressLesson,Number(b.dataset.progressStage||0));return;}setLesson(b.dataset.progressLesson);stage(Number(b.dataset.progressStage||0));});$$('[data-progress-review]').forEach(b=>b.onclick=()=>{if(state.subject==='maths'){maths.reviewTopic(b.dataset.progressReview);return;}setTopic(b.dataset.progressReview);startReview();});}
function date(t){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'Europe/London'}).format(new Date(t));}
function feedback(text,error=false){$('#feedback').textContent=text;$('#feedback').classList.toggle('error',error);}
function save(){state.view=view;state.courseId=state.subject==='science'?courseFor(state)?.id:null;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storage=false;}$('#saveStatus').textContent=storage?'Saved on this device':'Saved for this session';const count=available().filter(l=>{const p=session(state,l.id);updateCompletion(p,{...l,learnerTier:state.tier,learn:l.learn.filter(c=>!c.higher||state.tier==='Higher')},qs(l,'practice'),qs(l,'check'));return p.complete;}).length;$('#sideProgress').textContent=`${count} / ${available().length}`;$('#progressFill').style.width=count/available().length*100+'%';$('#reviewCount').textContent=reviewDue().length;updateProgressBadge();}
function refresh(){refreshStudio();updateProgressBadge();}
function refreshStudio(){cancelQuestionAdvance();save();$('#subject').value=state.subject;$('#route').value=state.route;$('#tier').value=state.tier;$('#studioLabel').textContent=subject().name+' studio';$('#lessonNav .nav-count').textContent=state.subject==='science'?allAvailable().length:'';$$('.nav').forEach(b=>b.classList.toggle('active',b.id===(view==='assessment'?'assessmentButton':view==='review'?'reviewButton':'lessonNav')));$('#courseName').textContent=subject().course;const science=state.subject==='science',mathsOn=state.subject==='maths';$('#scienceContent').hidden=!science;$('#plannedSubject').hidden=science||mathsOn;$('#mathsContent').hidden=!mathsOn;if(!mathsOn&&maths)$('#mathsContent').innerHTML='';$('#reviewButton').hidden=!science;$('#assessmentButton').hidden=!science;$('#sourceButton').hidden=!science;$('#reset').hidden=!science;$('#route').hidden=!science;$('#tier').hidden=!science;$('.side-course label').hidden=!science;$('.progress-label').hidden=!science;$('.progress-track').hidden=!science;$('.breadcrumb').textContent=science?'Science / '+topic().discipline:subject().name+' / GCSE';document.title=`Crash Course · ${science?current().title:subject().name}`;if(mathsOn){const m=mathsStudio();$('#reviewButton').hidden=false;$('#assessmentButton').hidden=false;$('#reset').hidden=false;$('#tier').hidden=false;$('#tier').value=m.tier();$('.progress-label').hidden=false;$('.progress-track').hidden=false;$('.breadcrumb').textContent='Maths';$('#lessonNav .nav-count').textContent='';m.render();document.title='Crash Course · '+m.title();return;}if(!science){$('#plannedSubject').innerHTML=`<div class="eyebrow">${safe(subject().name.toUpperCase())} STUDIO</div><h1>${safe(subject().name)}</h1><p>Lessons are not available yet.</p><button class="primary" id="backToScience">Science lessons →</button><button class="secondary" id="chooseSubject">Choose another subject</button>`;$('#backToScience').onclick=()=>switchSubject('science');$('#chooseSubject').onclick=openSubjects;return;}document.querySelector('label[for=topic]').textContent=topic().discipline+' topic';$('#topic').innerHTML=eligibleTopics().map(t=>`<option value="${t.id}">${safe(t.discipline)} · ${safe(t.title)}</option>`).join('');$('#topic').value=state.topicId;$('#studioName').textContent=topic().short.toUpperCase()+' STUDIO';if(view==='lesson')renderLesson();else renderRun();}
function switchSubject(id){state.subject=id;view='lesson';if($('#modal').open)$('#modal').close();refresh();}
function setLesson(id){const l=allAvailable().find(l=>l.id===id);if(!l)return;state.lastLessonByTopic[state.topicId]=state.lessonId;state.topicId=l.topicId;state.lessonId=id;state.lastLessonByTopic[l.topicId]=id;state.subject='science';view='lesson';if($('#modal').open)$('#modal').close();refresh();}
function setTopic(id){const list=topicLessons(lessons,id,state.route,state.tier);if(!list.length)return;const remembered=state.lastLessonByTopic[id];setLesson(list.some(l=>l.id===remembered)?remembered:list[0].id);}
function stage(n){session(state,state.lessonId).stage=n;feedback('');refresh();}
function renderLesson(){const l=current(),p=session(state,l.id);p.stage=Math.min(3,Math.max(0,p.stage||0));p.card=Math.min(l.learn.length-1,Math.max(0,p.card||0));const pqs=qs(l,'practice'),cqs=qs(l,'check');p.practiceIndex=Math.min(Math.max(0,p.practiceIndex||0),pqs.length-1);p.checkIndex=Math.min(Math.max(0,p.checkIndex||0),cqs.length-1);updateCompletion(p,l,pqs,cqs);syncProcessMovie(l,p.stage,p.stage===0?l.learn[p.card]:null);$('.intro h1').textContent=l.title;$('.intro>div>p').textContent='';$('.workspace').classList.toggle('question-mode',p.stage>=2);$('#lessonNumber').textContent=`LESSON ${String(available().findIndex(x=>x.id===l.id)+1).padStart(2,'0')} / ${available().length}`;$('#lessonMeta').innerHTML=`<div>◷ ${l.minutes} min</div>`;$('#bigIdea').textContent=l.big;$('#specRef').textContent='AQA '+specRefs(l,state.route).join(' / ');$('#lessonStatus').textContent=p.complete?`Complete · ${p.mastery}%`:'';$('#nextLessonButton').hidden=false;$('.steps').hidden=false;$$('.steps button').forEach((b,i)=>{const done=[l.learn.every((_,j)=>p.learnSeen.includes(j)),p.widgetDone,pqs.every(q=>p.practice[q.id]?.correct),grade(p.checks,cqs).finished&&p.mastery>=80][i];b.classList.toggle('selected',p.stage===i);b.classList.toggle('done',done);b.setAttribute('aria-current',p.stage===i?'step':'false');b.querySelector('b').textContent=done?'✓':`0${i+1}`;});$('#activityKicker').textContent=['DISCOVER','INVESTIGATE','PRACTISE','CHECK'][p.stage];$('#continue').hidden=false;$('#continue').disabled=false;$('#continue').textContent='Continue →';feedback('');if(p.stage===0){const c=l.learn[p.card];showScene(c.scene);$('#activityTitle').textContent=c.title;$('#activityBody').innerHTML=`${p.card===0&&l.prerequisites?.length?'<div class="prerequisites"><span>Prior learning:</span>'+l.prerequisites.map(id=>'<button class="text-button" data-prerequisite="'+id+'">'+safe(lessons.find(x=>x.id===id)?.title||id)+'</button>').join('')+'</div>':''}<p>${safe(c.text)}</p><div class="reading-dots">${l.learn.map((_,i)=>`<button data-card="${i}" aria-label="Explanation ${i+1}" class="${i===p.card?'current':''}">${i+1}</button>`).join('')}</div>`;$$('[data-prerequisite]').forEach(b=>b.onclick=()=>setLesson(b.dataset.prerequisite));$$('[data-card]').forEach(b=>b.onclick=()=>{p.card=Number(b.dataset.card);refresh();});$('#stageHint').textContent='';}else if(p.stage===1){$('#activityTitle').textContent='';mountWidget(l,p,$('#activityBody'),{save,feedback,done:()=>{updateCompletion(p,l,pqs,cqs);save();$('#stageHint').textContent='Complete ✓';}});$('#stageHint').textContent=p.widgetDone?'Complete ✓':'';}else if(p.stage===2){renderPractice(l,p,pqs);}else renderCheck(l,p,cqs);save();}
function optionEntries(q,seed=1){let h=2166136261;for(const c of q.id+':'+seed)h=Math.imul(h^c.charCodeAt(0),16777619);return q.options.map((text,i)=>{h^=h<<13;h^=h>>>17;h^=h<<5;return {text,i,key:h>>>0};}).sort((a,b)=>a.key-b.key);}
function questionFigure(q){if(!q.figure)return '';const f=q.figure;return '<div class="question-figure">'+(f.kind==='electric-symbol'?symbolAssessment(f):f.kind==='family-assessment'?familyAssessmentFigure(f):f.kind==='repro-figure'?reproAssessmentFigure(f):f.kind==='renal-figure'?renalAssessmentFigure(f):f.kind==='endo-figure'?endoAssessmentFigure(f):f.kind==='senses-assessment'?sensesAssessmentFigure(f):f.kind==='plant-leaf'?plantLeafFigure({neutral:true}):f.kind==='plant-graph'?plantGraph(f.points):f.kind==='health-plot'?healthPlot(f.chart,f):f.kind?.startsWith('bio-')?biologyFigure(f):f.kind==='catalyst'?catalystFigure(f):f.kind?.startsWith('rate-')?rateFigure(f):profileFigure(f))+'</div>';}
function answerControls(q,value,attr,locked,seed){if(q.type==='equation')return `<label class="field-label" for="equationAnswer">Your half-equation</label><input class="lab-input" id="equationAnswer" type="text" autocomplete="off" spellcheck="false" value="${value!==undefined?safe(value):''}" ${locked?'disabled':''}><p class="micro-note">Use ->, 3+ and e-. State symbols optional.</p><button class="secondary" id="submitAnswer" ${locked?'disabled':''}>Record answer</button>`;if(q.type==='number')return `<label class="field-label" for="numericAnswer">Your answer${q.unit?' · '+safe(q.unit):''}</label><input class="lab-input" id="numericAnswer" type="number" step="any" value="${value!==undefined?safe(value):''}" ${locked?'disabled':''}><button class="secondary" id="submitAnswer" ${locked?'disabled':''}>Record answer</button>`;return '<div class="choices">'+optionEntries(q,seed).map(({text:o,i})=>`<button class="choice ${value===i?'selected':''}" ${attr}="${i}" ${locked?'disabled':''}>${safe(o)}</button>`).join('')+'</div>';}
function bindAnswerEnter(selector){$(selector).onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();$('#submitAnswer').click();}};}
function bindAnswers(q,attr,callback){if(q.type==='equation'){bindAnswerEnter('#equationAnswer');$('#submitAnswer').onclick=()=>{const raw=$('#equationAnswer').value.trim();if(!raw){feedback('Enter a half-equation before recording your answer.',true);return;}callback(raw);};return;}if(q.type==='number'){bindAnswerEnter('#numericAnswer');$('#submitAnswer').onclick=()=>{const raw=$('#numericAnswer').value;if(raw.trim()===''||!Number.isFinite(Number(raw))){feedback('Enter a number before recording your answer.',true);return;}callback(Number(raw));};}else $$('['+attr+']').forEach(b=>b.onclick=()=>callback(Number(b.getAttribute(attr))));}
function answerText(q,value){return ['number','equation'].includes(q.type)?value===undefined?'Not answered':String(value):q.options[value]??'Not answered';}
function renderPractice(l,p,list){cancelQuestionAdvance();const q=list[p.practiceIndex],a=p.practice[q.id];showScene(l.id==='particles'?(q.prompt.includes('CO₂')?'carbon':q.prompt.includes('O₂')?'oxygen':'water'):l.learn[Math.min(1,l.learn.length-1)].scene);$('#activityTitle').textContent=q.prompt;$('#activityBody').innerHTML=questionFigure(q)+answerControls(q,a?.choice,'data-practice',!!a?.correct,p.run);if(a)feedback(a.correct?'Correct. '+q.why:'Try again. '+q.why,!a.correct);bindAnswers(q,'data-practice',choice=>{if(p.practice[q.id]?.correct)return;const correct=isCorrect(q,choice),old=p.practice[q.id];p.practice[q.id]={choice,correct,first:old?.first??choice,attempts:(old?.attempts||0)+1};recordConcept(state,q.concept,correct);if(correct&&!state.concepts[q.concept].needsReview)state.concepts[q.concept].due=Date.now()+86400000;save();renderPractice(l,p,list);});$('#stageHint').textContent=`Practice ${p.practiceIndex+1} / ${list.length}`;$('#continue').textContent=p.practiceIndex===list.length-1?'Start independent check →':'Next practice →';questionFlow($('#continue'),{answered:!!a?.correct,next:()=>$('#continue').click(),guard:()=>state.subject==='science'&&view==='lesson'&&current().id===l.id&&p.stage===2});}
function renderCheck(l,p,list){cancelQuestionAdvance();const q=list[p.checkIndex],a=p.checks[q.id];renderDiagram('Recall independently','No model hints',`<div class="recall-visual"><span>◎</span><h3>What stayed with you?</h3><p>Choose your answer before seeing the explanation.<br>Your first answer counts towards this check.</p><span class="recall-count">${p.checkIndex+1} / ${list.length}</span></div>`);$('#activityTitle').textContent=q.prompt;$('#activityBody').innerHTML='<p class="check-rule">First answers count.</p>'+questionFigure(q)+answerControls(q,a,'data-check',a!==undefined,p.run);bindAnswers(q,'data-check',choice=>{if(p.checks[q.id]!==undefined)return;p.checks[q.id]=choice;recordConcept(state,q.concept,isCorrect(q,choice));updateCompletion(p,l,qs(l,'practice'),list);save();renderCheck(l,p,list);feedback('Answer recorded.');});$('#stageHint').textContent=`Independent check ${p.checkIndex+1} / ${list.length}`;$('#continue').textContent=p.checkIndex===list.length-1?'See my results →':'Next question →';questionFlow($('#continue'),{answered:a!==undefined,delay:650,next:()=>$('#continue').click(),guard:()=>state.subject==='science'&&view==='lesson'&&current().id===l.id&&p.stage===3});}
$('#continue').onclick=()=>{if(view!=='lesson'){nextRun();return;}const l=current(),p=session(state,l.id),practice=qs(l,'practice'),checks=qs(l,'check');if(p.stage===0){if(!p.learnSeen.includes(p.card))p.learnSeen.push(p.card);if(p.card<l.learn.length-1)p.card++;else{const unread=l.learn.findIndex((_,i)=>!p.learnSeen.includes(i));if(unread>=0)p.card=unread;else p.stage=1;}refresh();}else if(p.stage===1){if(!p.widgetDone){feedback('Complete the activity to continue.',true);return;}p.stage=2;refresh();}else if(p.stage===2){if(!p.practice[practice[p.practiceIndex].id]?.correct){feedback('Answer this practice correctly before moving on.',true);return;}if(p.practiceIndex<practice.length-1)p.practiceIndex++;else p.stage=3;refresh();}else{if(p.checks[checks[p.checkIndex].id]===undefined){feedback('Choose an answer first.',true);return;}if(p.checkIndex<checks.length-1){p.checkIndex++;refresh();}else showResults();}};
function modal(html){cancelQuestionAdvance();document.dispatchEvent(new Event('question-flow:cancel'));$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
function resultRows(questions,rows){return questions.map(q=>`<details class="result-row"><summary><span class="${isCorrect(q,rows[q.id])?'right':'wrong'}">${isCorrect(q,rows[q.id])?'✓':'↻'}</span> ${safe(q.prompt)}</summary>${questionFigure(q)}<p>Your answer: ${safe(answerText(q,rows[q.id]))}<br>Correct answer: <strong>${safe(['number','equation'].includes(q.type)?q.answer:q.options[q.answer])}</strong><br>${safe(q.why)}</p></details>`).join('');}
function showResults(){const l=current(),p=session(state,l.id),checks=qs(l,'check'),g=grade(p.checks,checks);updateCompletion(p,l,qs(l,'practice'),checks);save();const pending=[];if(!l.learn.every((_,i)=>p.learnSeen.includes(i)))pending.push('Discover explanations');if(!p.widgetDone)pending.push('interactive lab');if(!qs(l,'practice').every(q=>p.practice[q.id]?.correct))pending.push('practice');if(g.percent<80)pending.push('a check score of at least 80%');modal(`<span class="eyebrow">LESSON CHECK · RUN ${p.run}</span><h2>${g.correct} / ${g.total} · ${g.percent}%</h2><p>${pending.length?'To complete this lesson, finish '+pending.join(', ')+'.':'Lesson complete. Your next recall review is '+date(p.reviewAt)+'.'}</p>${resultRows(checks,p.checks)}<div class="modal-actions"><button class="primary" id="resultNext">${pending.length?'Continue learning':'Next lesson →'}</button><button class="secondary" id="retake">Try the check again</button><button class="secondary" id="resultReview">Review concepts</button></div>`);$('#retake').onclick=()=>{p.history??=[];p.history.push({run:p.run,score:g.percent,answers:{...p.checks},at:Date.now()});p.run++;p.checks={};p.checkIndex=0;p.stage=3;$('#modal').close();refresh();};$('#resultNext').onclick=()=>{if(pending.length){$('#modal').close();p.stage=!l.learn.every((_,i)=>p.learnSeen.includes(i))?0:!p.widgetDone?1:!qs(l,'practice').every(q=>p.practice[q.id]?.correct)?2:3;refresh();}else nextLesson();};$('#resultReview').onclick=startReview;}
function nextLesson(){const all=available(),index=all.findIndex(l=>l.id===state.lessonId);if(index<all.length-1)setLesson(all[index+1].id);else openTopics();}
function topicLinks(){return '<div class="course-topics">'+['Biology','Chemistry','Physics'].map(name=>'<section class="course-topic-group"><h3>'+name+'</h3><div class="topic-links">'+eligibleTopics().filter(t=>t.discipline===name).map(t=>`<button class="topic-link" data-open-topic="${t.id}" ${t.id===state.topicId?'aria-current="page"':''}><span>${safe(t.title)}</span><span aria-hidden="true">→</span></button>`).join('')+'</div></section>').join('')+'</div>';}
function bindTopicLinks(){$$('[data-open-topic]').forEach(b=>b.onclick=()=>setTopic(b.dataset.openTopic));}
function openTopics(){modal('<span class="eyebrow">SCIENCE</span><h2>Choose a topic</h2>'+topicLinks());bindTopicLinks();}
function openLessons(){modal(`<span class="eyebrow">${safe(topic().discipline.toUpperCase())} · TOPIC ${topic().number}</span><h2>${safe(topic().title)}</h2><p>${state.route==='combined'?'Combined Science: Trilogy':'Separate '+topic().discipline} · ${state.tier}.</p><button class="text-button" id="chooseTopic">Choose another topic ↗</button><div class="lesson-list">${available().map((l,i)=>{const p=session(state,l.id);return `<button class="lesson-row" data-lesson="${l.id}"><span class="lesson-row-number">${p.complete?'✓':String(i+1).padStart(2,'0')}</span><span><b>${safe(l.title)}</b><small>${l.minutes} min · ${l.separate?'Separate '+topic().discipline:'Both routes'}${l.higher?' · Higher only':''} · ${p.complete?'Complete':p.learnSeen.length||p.widgetDone||Object.keys(p.checks).length?'In progress':'Ready'}</small></span><span>→</span></button>`;}).join('')}</div><div class="modal-actions"><button class="primary" id="mapAssess">${topic().status==='partial'?'Available-lesson':'Topic'} assessment →</button><button class="secondary" id="mapReview">Review & recall</button></div>`);$$('[data-lesson]').forEach(b=>b.onclick=()=>setLesson(b.dataset.lesson));$('#chooseTopic').onclick=openTopics;$('#mapAssess').onclick=startAssessment;$('#mapReview').onclick=startReview;}
function openSubjects(){modal('<span class="eyebrow">CRASH COURSE</span><h2>Choose your subject.</h2><div class="subject-grid">'+subjects.map(s=>`<button class="subject-card ${s.id===state.subject?'selected':''}" data-subject="${s.id}"><b>${safe(s.name)}</b><span>${safe(s.description)}</span><small>${s.status==='available'?(s.id==='science'?'Science lessons available':'Maths lessons available'):'Planned'}</small></button>`).join('')+'</div>');$$('[data-subject]').forEach(b=>b.onclick=()=>switchSubject(b.dataset.subject));}
function openMap(){if(state.subject!=='science'){modal(`<span class="eyebrow">${safe(subject().name.toUpperCase())} COURSE MAP</span><h2>${safe(subject().course)}</h2><p>Lessons for this subject are not available yet.</p><button class="primary" id="subjectsAgain">Choose a subject →</button>`);$('#subjectsAgain').onclick=openSubjects;return;}modal('<span class="eyebrow">SCIENCE</span><h2>Course map</h2>'+topicLinks());bindTopicLinks();}
function shuffle(a){const list=[...a];for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}return list;}
function allQuestions(){return available().flatMap(l=>[...qs(l,'practice'),...qs(l,'check')].map(q=>({...q,lessonId:l.id})));}
function startAssessment(){if(assessment()&&!assessment().finished&&assessment().route===state.route&&assessment().tier===state.tier){view='assessment';if($('#modal').open)$('#modal').close();refresh();return;}modal(`<span class="eyebrow">INDEPENDENT TOPIC ASSESSMENT</span><h2>${safe(topic().title)}</h2><p>${available().length} questions, one from each available lesson. ${topic().status==='partial'?'This checks available lessons, not the full topic.':''} First answers count. Results include explanations. Pass mark: 80%.</p><button class="primary" id="beginAssessment">Start assessment →</button>`);$('#beginAssessment').onclick=()=>{const queue=shuffle(available().map(l=>({...shuffle(qs(l,'check'))[0],lessonId:l.id})));if(assessment()?.finished){state.assessmentHistory??=[];state.assessmentHistory.push(assessment());}state.assessments[contextKey(state)]={topicId:state.topicId,route:state.route,tier:state.tier,queue,answers:{},index:0,finished:false,startedAt:Date.now()};view='assessment';$('#modal').close();refresh();};}
function reviewDue(){const allowed=new Set(allQuestions().map(q=>q.concept));return dueConcepts(state).filter(k=>allowed.has(k));}
function startReview(){const active=reviewSession();if(active&&!active.finished&&active.queue?.length){view='review';if($('#modal').open)$('#modal').close();refresh();return;}const pool=allQuestions(),due=reviewDue(),completed=available().filter(l=>session(state,l.id).complete);const candidates=due.length?pool.filter(q=>due.includes(q.concept)):pool.filter(q=>completed.some(l=>l.id===q.lessonId));const unique=[];shuffle(candidates).forEach(q=>{if(!unique.some(x=>x.concept===q.concept))unique.push(q);});if(!unique.length){modal('<h2>Your recall list starts here.</h2><p>Complete a lesson or attempt some questions. Concepts you find difficult will appear here immediately; completed learning returns for spaced recall.</p><button class="primary" id="reviewLessons">Choose a lesson →</button>');$('#reviewLessons').onclick=openLessons;return;}const dueCount=unique.length;modal(`<span class="eyebrow">SPACED RECALL</span><h2>${dueCount} concept${dueCount===1?'':'s'} to revisit.</h2><p>${due.length?'These concepts are due or need more practice.':'Nothing is due yet. This is an optional early review of completed lessons.'} Successful recall schedules the next review after 1, 3, 9, then 21 days. A missed answer brings the concept back sooner.</p><p>${unique.map(q=>safe(conceptNames[q.concept]||q.concept)).join(' · ')}</p><button class="primary" id="beginReview">Start recall →</button>`);$('#beginReview').onclick=()=>{state.reviewSessions[contextKey(state)]={topicId:state.topicId,route:state.route,tier:state.tier,queue:unique.slice(0,12),answers:{},index:0,finished:false};view='review';$('#modal').close();refresh();};}
function renderRun(){cancelQuestionAdvance();syncProcessMovie(null,3);const run=view==='assessment'?assessment():reviewSession();if(!run||run.finished){view='lesson';renderLesson();return;}$('.steps').hidden=true;$('#nextLessonButton').hidden=true;const q=run.queue[run.index],a=run.answers[q.id];$('.intro h1').textContent=view==='assessment'?'Topic assessment':'Review';$('.workspace').classList.add('question-mode');$('.intro>div>p').textContent='';$('#lessonNumber').textContent=view==='assessment'?'TOPIC CHECK':'SPACED REVIEW';$('#lessonMeta').innerHTML='';$('#lessonStatus').textContent='';$('#activityKicker').textContent=view==='assessment'?'ASSESSMENT':'REVIEW';$('#activityTitle').textContent=q.prompt;$('#bigIdea').textContent=view==='assessment'?'First answers count. Explanations and a concept breakdown appear after the final question.':'Recall strengthens learning. A missed answer identifies a concept to revisit.';$('#specRef').textContent='AQA · '+topic().short.toUpperCase();renderDiagram('Recall independently','One question at a time',`<div class="recall-visual"><span>◎</span><h3>${view==='assessment'?'Connect your learning.':'Make it stay.'}</h3><p>${run.index+1} of ${run.queue.length}</p></div>`);$('#activityBody').innerHTML=(view==='assessment'?'<p class="check-rule">First answers count.</p>':'')+questionFigure(q)+answerControls(q,a,'data-run',a!==undefined,run.startedAt||1);bindAnswers(q,'data-run',choice=>{if(run.answers[q.id]!==undefined)return;run.answers[q.id]=choice;recordConcept(state,q.concept,isCorrect(q,choice),Date.now(),view==='review');save();renderRun();if(view==='review')feedback((isCorrect(q,choice)?'Correct. ':'Revisit this idea. ')+q.why,!isCorrect(q,choice));else feedback('Answer recorded.');});feedback('');if(view==='review'&&a!==undefined)feedback((isCorrect(q,a)?'Correct. ':'Revisit this idea. ')+q.why,!isCorrect(q,a));$('#stageHint').textContent=`${run.index+1} / ${run.queue.length}`;$('#continue').hidden=false;$('#continue').textContent=run.index===run.queue.length-1?'See results →':'Next question →';questionFlow($('#continue'),{answered:a!==undefined,automatic:view==='assessment'||isCorrect(q,a),delay:view==='assessment'?650:2400,next:nextRun,guard:()=>state.subject==='science'&&view!=='lesson'});save();}
function nextRun(){const run=view==='assessment'?assessment():reviewSession(),q=run.queue[run.index];if(run.answers[q.id]===undefined){feedback('Choose an answer before continuing.',true);return;}if(run.index<run.queue.length-1){run.index++;refresh();return;}run.finished=true;run.finishedAt=Date.now();const g=grade(run.answers,run.queue);run.score=g.percent;save();const assessing=view==='assessment';modal(`<span class="eyebrow">${assessing?'TOPIC ASSESSMENT':'RECALL RESULTS'}</span><h2>${g.correct} / ${g.total} · ${g.percent}%</h2><p>${assessing?g.percent>=80?'You reached the 80% threshold for these available lessons. Check missed concepts and continue building evidence of understanding.':'Keep working on the missed concepts before trying another assessment.':'Correct recall has scheduled your next review. Missed concepts remain on your review list.'}</p>${resultRows(run.queue,run.answers)}<div class="modal-actions"><button class="primary" id="runLessons">Back to lessons →</button><button class="secondary" id="runReview">Review weak concepts</button></div>`);$('#runLessons').onclick=()=>{view='lesson';$('#modal').close();refresh();};$('#runReview').onclick=()=>{view='lesson';startReview();};view='lesson';renderLesson();}
$('#progressButton').onclick=openProgress;$('#subject').onchange=e=>switchSubject(e.target.value);$('#route').onchange=e=>{state.route=e.target.value;Object.assign(state,eligibleSelection(lessons,state.topicId,state.lessonId,state.route,state.tier,state.lastLessonByTopic));view='lesson';refresh();};$('#tier').onchange=e=>{if(state.subject==='maths'){mathsStudio().setTier(e.target.value);return;}state.tier=e.target.value;Object.assign(state,eligibleSelection(lessons,state.topicId,state.lessonId,state.route,state.tier,state.lastLessonByTopic));view='lesson';refresh();};$('#lessonNav').onclick=()=>state.subject==='science'?openLessons():state.subject==='maths'?mathsStudio().openLessons():openSubjects();$('#topic').onchange=e=>setTopic(e.target.value);$('#lessonsButton').onclick=openLessons;$('#nextLessonButton').onclick=nextLesson;$('#mapButton').onclick=()=>state.subject==='maths'?mathsStudio().openMap():openMap();$('#reviewButton').onclick=()=>state.subject==='maths'?mathsStudio().startReview():startReview();$('#assessmentButton').onclick=()=>state.subject==='maths'?mathsStudio().startAssessment():startAssessment();$$('[data-stage]').forEach(b=>b.onclick=()=>{view='lesson';stage(Number(b.dataset.stage));});
$('#modelNotesButton').onclick=()=>$('#sourceButton').click();
$('#sourceButton').onclick=()=>{const l=current();const physicsNotes={"rad1": "Nuclear/electron scales, waiting times, paths and rare-event frequencies schematic. Expected decay is not an individual schedule. Qualitative barriers do not calculate dose; original medical comparisons are not clinical data. Writing nuclear equations and unrestricted explanations remain separate.", "frc1": "Forces and trajectories use independent display scales. Read the selected relationship, SI units and direction convention. Conditions include fixed mass/force, linear elastic region, homogeneous static fluids or ideal closed collisions as stated. Generated graphs and constrained vectors do not establish unrestricted construction or physical practical performance.", "wav1": "Particles oscillate locally while patterns transfer energy. Playback slowed independently of SI values; real water-surface paths are more complex. Ray/spectrum diagrams are schematic; exact optical constants and full spectra omitted. Supplied lens heights are a separate ratio account, not derived from the fixed ray drawing. Echoes assume one boundary and a homogeneous medium. Real measurements and unrestricted graph/ray construction remain separate.", "mag1": "Field lines represent direction/relative strength, not physical strings. Prescribed coil rotation and vibration explain conversion rather than solve load/speed response. Conventional current, magnetic field and force directions are distinct. Reference wiring sets induced sign; an induced current needs a complete circuit. Core saturation, leakage and losses omitted from ideal transformer accounts.", "spa1": "Sizes, separations, orbital periods and evolutionary/cosmological time scales independently exaggerated. Stellar pathways depend on mass. A circular-orbit direction model is not an inverse-square calculation. Expanding grid/redshift analogy is not a calibrated cosmological law. Open questions about dark matter/energy are retained."};const ns=l.widget.slice(0,4);if(physicsNotes[ns]){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')}; checked22October2026. The selected course and tier determine available lessons and Higher extensions.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">Official AQA specification ↗</a></p><p>${safe(physicsNotes[ns])}</p><p>Original teaching and model data. Technical checks do not constitute specialist review. Physical school practicals and independent constructed evidence remain separate.</p>`);return;}if(l.widget.startsWith('mat2-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')}; checked22October2026. Thermal/gas core shared both tiers. Pressure–volume4.3.3.2 is separate Physics both tiers; work/pump warming4.3.3.3 is separate Higher only, filtered again at completion.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Original toy material, not water: c1000J/(kg°C), melt20°C/fusion10000J/kg, boil80°C/vaporisation20000J/kg. Curve1kg/1000W at fixed pressure without losses;120model seconds, with each region given equal playback time for clarity. Cooling reverses the energy account. mcΔθ applies within a phase; mL to a state change. Existing Energy specific-heat-capacity lesson supplies shared equation/practical preparation; latent-fusion AT5 is an opportunity, not a new required practical.</p><p>Particle size/count fixed; trajectories, speeds and impact arrows illustrative, not calibrated collision statistics or numerical pressure/temperature law. Constant-temperature compression uses absolute pressure and fixed mass; a reservoir maintains temperature. Higher quick insulated compression can warm gas and does not use pV constant. Friction/leaks/real pump dynamics omitted. Films are worked examples independent of saved controls. Physical practical, uncertainty, unrestricted graph/writing and specialist evidence remain separate from technical QA.</p>`);return;}if(l.widget.startsWith('mat1-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')}; checked22October2026. Static lessons: separate Physics, both tiers. Particle lessons: both routes/tiers.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Electrons transfer; protons remain bound. Counts, force arrows and suspended motion are symbolic. Repulsion shows like charged objects; attraction alone does not establish opposite net charge. Radial arrows use positive-test-charge direction; no Coulomb law or numerical field strength. Sparks are conceptual air conduction, not a high-voltage activity.</p><p>Density preparation: ${state.route==='combined'?'Trilogy RP17':'Physics RP5'}, AT1, regular dimensions, irregular displacement and liquid container subtraction. Original readings assume full immersion/no absorption/bubbles; images are not scales. Real apparatus, resolution and uncertainty competence remain school evidence. State changes conserve closed-system mass; open evaporation changes the measured boundary. Fixed particle size; schematic motion/timing, no temperatures or latent-heat model. See process transcripts for each worked example. Technical QA is not specialist review, unrestricted field drawings or physical practical competence.</p>`);return;}if(l.widget.startsWith('el3-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')}. Checked22October2026. Shared core, both tiers. Grid ideal-transformer balance is Higher: Trilogy6.2.4.3; separate Physics4.7.3.4 cross-topic scaffold. Coil construction and turns ratio are taught in the separate Higher Magnetism transformer lesson.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>AC trace normalised, not230V peak; playback slowed. Mains voltages nominal, not instantaneous. Conceptual protected earthed appliance only; no live-mains experiment, real fault-current or trip-time simulation. An open switch does not isolate every live part.</p><p>P=VI, P=I²R, E=Pt and E=QV use SI units. Constant input-power accounts do not assume100% useful output. Grid toy voltages and1Ω total line resistance illustrate I=P/V and cable loss I²R; received power is sending power minus loss. Transformer/network losses and regulation omitted. Films are worked examples, separate from saved experiment controls. Technical QA is not specialist review or physical practical competence.</p>`);return;}if(l.widget.startsWith('el2-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · both routes and tiers. Checked22October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}. Ideal sources/resistors: same series current, componentpd sum, equalpd across closed parallel branches and branch-current sum. An open branch is visibly broken and has zero current; sourcepd is not assigned across its isolated resistor. No parallel equivalent-resistance formula or numerical assessment required. Tracers are conventional-current direction markers, not carrier speed/energy packets or literal charge counts.</p><p>${state.route==='combined'?'Trilogy RP15':'Physics RP3'} combinations preparation, alongside the wire-length lesson, addresses both planned teaching parts; physical setup, measurements, risk assessment and uncertainty remain school evidence. Series ammeter and voltmeter across the selected component/group. Supply off before rewiring. AT1/6/7.</p><p>Thermistor and LDR AT6 investigations use original bounded curves. Temperature20–60°C and light-index0–100 are prescribed inputs, not feedback outcomes or calibration. Sensor resistance falls with increasing stimulus; at fixedpd sensor current rises. The chosen controller commands heating below40°C or a lamp below light-index50; it is a block scaffold with separate power stage omitted. Those thresholds/timings are arbitrary, not required equations or device ratings. No self-heating, lag or hysteresis model.</p><p>Watching, constrained calculations and selected reasoning do not establish independent unrestricted drawing/graphs/writing, physical apparatus skills or specialist review. Other Electricity sections and earlier Energy/Biology evidence audits remain open.</p>`);return;}if(l.widget.startsWith('el1-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · both routes and tiers. Checked22October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}. Standard symbol forms are original SVG renditions checked against AQA’s symbol sheet; independent freehand drawing remains further evidence. All measured values and curves are original illustrations. Conventional-current tracers are not electrons or energy particles; single-loop current is the same throughout. Q=It and V=IR use C,A,s,V and Ω.</p><p>${state.route==='combined'?'Trilogy RP15':'Physics RP3'} wire-length preparation is one part: use the Resistor combinations lesson for the other part; physical work remains. ${state.route==='combined'?'Trilogy RP16':'Physics RP4'} I–V preparation includes resistor at constant temperature, filament lamp and diode. Meter connections, current limiting and supply-off rewiring support supervised school practicals. AT1/6/7 wire; AT6/7 IV.</p><p>Wire R=2L/A and component I–V functions are toy assumptions, not required equations, real material coefficients, device ratings or construction guidance. Lamp curve is qualitative; diode zero reverse current omits leakage. No numerical V/0 resistance. Watching or selected/numeric answers do not demonstrate unrestricted graph/diagram/written evidence, physical apparatus skills or specialist review. Sensor behaviour/applications now have their own lessons; domestic electricity and electrical energy remain planned.</p>`);return;}if(l.widget.startsWith('phy2-')){modal(`<p class="eyebrow">SPECIFICATION & MODEL NOTES</p><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(' / ')} · both routes and tiers; efficiency-improvement extension Higher only. Checked22 October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}. Original energy/work, time, cooling and supply examples. Power uses J/s=W; efficiency uses matching energy or power units and has no unit. Closed allocation accounts conserve input. Moving markers are symbolic pathways, not energy particles. Motor model time is explicitly0–4s, stretched for viewing.</p><p>Cooling uses an original exponential toy curve, uniform block, fixed20°C surroundings and conductivity/thickness indices. It is not a required equation, calibrated property or building forecast. ${state.route==='separate'?'Separate Physics insulation RP2 preparation, AT1/5.':'Trilogy conduction teaching; insulation RP2 is not a Trilogy required practical.'} Rod investigation AT1/5 is a shared opportunity. Real school measurements and risk assessment remain necessary.</p><p>Wind capacity/output and100-unit resource trends are fictional classroom data, not current national statistics or forecasts. The wind balance omits storage, prices and other generation. Science informs environmental choices alongside social, political, ethical and economic considerations. Watching, constrained calculations and selected reasoning do not establish unrestricted written/graph evidence, specialist review or practical competence.</p>`);return;}if(l.widget.startsWith('phy1-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · Trilogy and separate Physics · both tiers. Checked22 October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}.</p><p>Original equation-based examples. Mass in kg; speed in m/s; height and extension in m; g is supplied, not a universal10N/kg. Spring relation assumes a supported proportional range. Chosen objects and surroundings define the closed400J accounts. Cart travel duration, dimensions and illustrative lifting/spring motion are symbolic. The ideal launch is2kg at20m/s with g10, total400J; playback stretches a4s trajectory. Replaying resets examples, not nature or your experiment.</p><p>The virtual block has c1000J/(kg°C), uniform temperature, no phase change and original readings. Heater input differs from block gain with losses. A full apparatus investigation requires physical school measurements and risk assessment.${l.widget==='phy1-heating'?' SHC practical: '+(state.route==='combined'?'Trilogy RP14':'Physics RP1')+'; AT1/5.':''} Constrained numeric/selected reasoning is not unrestricted writing/graph evidence or specialist certification.</p>`);return;}if(l.widget.startsWith('eco6-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · Separate Biology · both tiers. Checked22 October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}.</p><p>Original fictional energy allocations, fish counts and product units. The farm account holds intake fixed and omits real physiology, feed changes and housing requirements; output does not resolve welfare. The fish model starts40 juveniles/60 adults, removes a20/60 adult target plus10 juvenile bycatch with small mesh (none with large mesh), then adds recruits equal to half surviving adults. This is a one-cycle teaching rule, not legal quota guidance or a calibrated forecast; maturation, natural mortality, migration and density dependence are omitted.</p><p>Fusarium is a fungus; insulin is a different product from a GM bacterium. Glucose/oxygen output units are illustrative, not balanced molecular yields. Zero in the no-oxygen version describes this aerobic process, not universal fungal survival. Vessels, mesh, particles and timings are symbolic, not culture protocols or clinical instructions. Movies are worked examples separate from saved controls.</p><p>Constrained comparisons and selected conclusions are not independent extended argument writing. Roadmap completion is separate from specialist review, full statement reconciliation and broader evidence gaps.</p>`);return;}if(l.widget.startsWith('eco5-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · ${l.separate?'Separate Biology':'Trilogy and separate Biology'} · both tiers. Checked22 October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}.</p><p>Original fictional costs, habitat/waste outcomes, biomass values and food-equivalent units. A conservation target does not rank all ecological benefits or guarantee survival. Biomass widths use one common linear scale; tiny bars are not secretly enlarged. Construction is constrained entry, not unrestricted freehand evidence.</p><p>About1% incident light energy and about10% biomass transfer compare different quantities and are approximate. The100-unit allocation follows original organic material; incoming oxygen, product masses, urinary and other routes are omitted from its numbers. It is not a full mass/energy budget. Feeding signals are not transforming organisms. Enzymes act outside before soluble products diffuse in; shapes and times are symbolic.</p><p>Food availability can differ from production; aggregate demand ignores individual access and dietary needs. Food-equivalent units are not nutrition advice. Movies are separate worked examples; watching does not complete investigation. Independent extended writing, unrestricted diagrams and specialist review remain outstanding.</p>`);return;}if(l.widget.startsWith('eco4-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · shared both tiers. Checked22 October2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}.</p><p>Original teaching data and symbolic diagrams. Equal-area species samples, pollutant units, hectares, compost prices and temperature anomalies are fictional examples. A food link does not guarantee survival; habitat area is not a species-mortality percentage. Carbon is transferred, not created. Peat formation and process timings are not calibrated. Greenhouse arrows show qualitative energy routes, not an impermeable lid or a complete energy budget. Climate anomalies are differences from one baseline, not absolute temperatures or current observations.</p><p>Movies are separate worked examples; replay does not change your saved work. Comparisons and ordered explanations prepare evaluation, but do not establish independent extended writing or unrestricted graphing. Specialist review remains outstanding.</p>`);return;}if(l.widget.startsWith('eco3-')){modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA ${specRefs(l,state.route).join(', ')} · ${l.separate?'Separate Biology':'Trilogy and separate Biology'} · ${l.higher?'Higher only':'Both tiers'}. Checked 22 October 2026.</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">AQA specification ↗</a></p><p>Skills: ${safe(l.skills.join(', '))}.</p><p>Carbon and water boxes are selected combined stores. Fixed movie counts show a starting account; the moving marker traces a route. Your investigation transfers are separate and conserve material. Energy does not cycle identically. Timings, colours and token sizes are symbolic.</p><p>Compost mass loss is an original illustrative comparison, not a universal rate or destruction of matter. Biogas contains methane among other gases. The lipase classroom model releases fatty acids; natural milk decay involves lactic acid. Original endpoint timings, linear pH progress and indicative colour are teaching devices. Common-endpoint 1/time compares relative rates; it does not count microorganisms.</p><p>Distribution thresholds and water/CO₂ indices are fictional. Suitable model sites are not observed abundance, migration or worldwide extinction; the gas change is a local hypothetical scenario.</p>${l.widget==='eco3-decay-practical'?'<p>Required practical 10 preparation: temperature and fresh-milk decay using pH. AT1/3/4/5; real supervised measurement, safe handling and contemporaneous records remain required. Constrained graph entry does not establish unrestricted graphing or physical competence.</p><p><a href="https://www.aqa.org.uk/subjects/biology/gcse/biology-8461/specification/practical-assessment" target="_blank" rel="noopener">AQA practical requirements ↗</a> · <a href="https://filestore.aqa.org.uk/resources/biology/AQA-8461-PRACTICALS-HB.PDF" target="_blank" rel="noopener">Illustrative practical handbook ↗</a></p>':''}<p>Original content and data. Technical checks are separate from specialist review.</p>`);return;}modal(`<span class="eyebrow">SPECIFICATION & MODEL NOTES</span><h2>${safe(l.title)}</h2><p>AQA references: ${specRefs(l,state.route).join(', ')}. ${l.separate?'Separate '+topic().discipline+' only.':'Shared across Trilogy and separate '+topic().discipline+'.'} ${l.higher?'Higher Tier only.':'Both tiers; any Higher extensions are shown only on Higher.'}</p><p><a href="${topic().sources[state.route]}" target="_blank" rel="noopener">Open the AQA specification ↗</a></p>${l.extraSource?'<p><a href="'+(state.route==='combined'?'https://www.aqa.org.uk/subjects/science/gcse/science-8464/specification/biology-subject-content':l.extraSource)+'" target="_blank" rel="noopener">Related resistance specification ↗</a></p>':''}${l.widget==='photo-practical'?'<p>Practical preparation: '+(state.route==='combined'?'Trilogy required practical5':'Biology required practical6')+'; AT1,2,3,4,5.</p>':''}${l.widget==='food-tests'?'<p>Practical preparation: '+(state.route==='combined'?'Trilogy required practical3; AT2':'Biology required practical4; AT2,8')+'.</p>':l.widget==='amylase-practical'?'<p>Practical preparation: '+(state.route==='combined'?'Trilogy required practical4; AT1,2,5':'Biology required practical5; AT1,2,5,8')+'.</p>':''}${l.widget==='neuro-reaction-time'?'<p>Practical preparation: '+(state.route==='combined'?'Trilogy required practical6':'Biology required practical7')+'; AT1,3,4. Physical school practical work remains required.</p>':''}<p>Lesson skill mappings: ${safe(l.skills.filter(skill=>!(state.route==='combined'&&['food-tests','amylase-practical'].includes(l.widget)&&skill==='AT8')).join(', '))}. These are authoring mappings, not a claim that each code is explicitly printed beside every paragraph.</p><p><strong>Current model:</strong> ${safe($('#sceneKicker').textContent)}.</p><p>${topic().discipline==='Biology'?(l.widget.startsWith('neuro-')?'Neurone shapes, synaptic cleft, transmitter particles and pathway spacing are enlarged schematics, not micrographs. Impulse tracers are signals, not moving blood or material boluses; stage time and speed are symbolic. Chemical synapse detail is a mechanism scaffold supporting required structure/function. Generic target correction is not a hormone or patient simulation. Reaction-time records are original supplied data; rounded free-fall ruler conversions are not a personal device timer or fitness diagnosis. Constrained plotting and simulation do not replace physical school practical work.':l.widget.startsWith('resp-')?'Respiration models and process films are schematic: mitochondrial folds, building blocks, transport routes and stage durations are symbolic. Energy markers are qualitative, not ATP counts. Seed temperatures, pulse and oxygen-use records are original illustrative data, not physiological forecasts or fitness assessments. Higher lactic-acid recovery follows the simplified AQA account rather than a complete biochemical pathway. Lipid bars and carbohydrate/protein bead groupings represent building blocks, not molecular geometry. Exercise investigation opportunities (AT1,3,4) require supervised physical work; this simulation does not establish practical competence. Films are worked examples separate from experiment settings.':l.widget.startsWith('photo-')?'Photosynthesis models are symbolic: chloroplast/grana dimensions, particle inventories and apparatus routes are schematic rather than molecular structures or construction instructions. Rate curves, gas readings and greenhouse finances are original illustrative data, not biological calibrations. Inverse-square calculations assume a suitable point-source approximation for light, not an identical law for biological rate. Oxygen collection is a practical proxy affected by dissolved gas/respiration; bubble size varies. Constrained graph plotting and simulation preparation do not establish real school apparatus, safety or unrestricted graphing competence.':l.widget.startsWith('separatebio-')?'Hybridoma cells, antigen binding, assay strips and plant structures are original schematics with symbolic shapes, scale, colours and discrete stages. The supplied antigen-A test is a mechanism analogy with explicit T/C rules, not clinical evidence or a real diagnostic kit. Plant signs and nutrient comparisons are not specimen diagnosis or calibrated growth rates. Targeted delivery aims to minimise non-target harm but does not guarantee no adverse effects. Mimicry is a supplied example, not a universal behaviour.':l.widget.startsWith('medicine-')?'Medicine models use symbolic antigen shapes, counts, stages and source plants. Network contacts, perfect protection and no recovery are assumptions, not measured risk or a real vaccination threshold. Resistance acts on variants present before selection. Screening, dose and trial data are original classroom examples in arbitrary units, not treatment advice or clinical evidence. Sources are not botanical identification. Peer review is scrutiny, not certainty.':l.widget.startsWith('infection-')?'Infection models are original qualitative comparisons. Shapes, colours, sizes, stage spacing and route blocks are symbolic, not diagnostic images, measured transmission rates, personal risk estimates or treatment predictions. Pathogen types are separately enlarged. Viral replication needs living cells. Malaria lifecycle detail and incubation are omitted; the mosquito is a vector. Antigen binding is a shape analogy; antitoxin action differs from engulfment.':l.widget.startsWith('plant-')?'Plant cutaways, particles, pore sizes and layer spacing are symbolic, not real micrographs or calibrated biological rates. Potometer uptake estimates transpiration but is not identical to water loss. Sampling fields and graph data are original illustrations; a constrained label/plot activity does not establish physical microscope, drawing or apparatus competence. Environmental comparisons assume moderate conditions and adequate water; stress can close stomata.':l.widget.startsWith('health-')?'Health models use original illustrative data and symbolic geometry, not measured blood flow, growth rates, personal risk scores or clinical treatment advice. Artery widths and tumour steps are schematic. Risk is not certainty; correlation alone does not prove causation. Histograms use equal-width classes; plots are constrained construction, not unrestricted freehand evidence.':(l.widget.startsWith('plant-')||l.widget.startsWith('health-')||['heart-lab','circulation-route','vessel-lab','blood-lab','lung-lab','food-tests','amylase-practical','digestive-enzymes','enzyme-conditions','bile-lab','organisation-levels','digestion-route','enzyme-fit'].includes(l.widget)?'Circulation chambers, vessel walls, blood components and alveoli are functional schematics; colours and scales are symbolic. Blood is never blue. Gas counts conserve model units in a closed comparison, not real lung concentrations, rates or time. Counterfactuals isolate one role, not a complete disease mechanism. Food-test observations and amylase sampling/graph data are original simulations. Written observations accompany colour.30s sampling brackets an endpoint rather than measuring an exact instant. Organisation layers, digestive routes and active-site shapes are schematic. Scales differ between hierarchy levels. Enzyme fit is a simplified analogy. Condition curves/product values are original illustrative comparisons, not measured or universal optima/rates. Equal-volume fat cubes model exposed area, not molecular breakdown. Shapes, particles and steps are not molecular structures or a literal organ dissection.':['culture-lab','growth-lab','zone-lab'].includes(l.widget)?'School culture equipment, colonies and zones are schematic. Growth calculations assume a supplied mean division time with suitable nutrients/conditions and no deaths. Clear-zone results are original illustrative data, not clinical evidence. Real microbiology needs approved organisms, supervision and risk assessment.':['active-lab','transport-compare'].includes(l.widget)?'Membrane machinery and particle shapes are schematic. Counts represent equal comparison volumes; steps are illustrative, not biological rates or an ATP budget. Turning off the selected active route does not stop passive molecular movement.':['osmosis-lab','osmosis-practical'].includes(l.widget)?'Water crosses the model membrane; solute stays on its side. Reservoir conditions, cell volumes and transfer counts are symbolic. Original practical data and graphs prepare for real measurements; they do not establish hands-on competence.':['diffusion-lab','surface-lab','exchange-lab'].includes(l.widget)?'Particle transfers are illustrative snapshots in equal volumes, not calibrated biological rates. Cube penetration represents geometry at a chosen depth, not a measured time. Exchange-surface drawings are conceptual counterfactuals, not accurate organ anatomy.':'Cells and organelles are schematic cutaways with symbolic colours and exaggerated sizes. They are not photographs, electron micrographs or accurate molecular models. The microscope view is a simulation; focus and view enlargement do not establish real resolving power.')): 'Atoms are not solid coloured balls. Nuclei, shells, bonds, scattering paths and apparatus are schematic and not to scale. Colour is symbolic. Shell filling is restricted to the first20 elements.'} Simulations support learning and do not replace required school practicals.</p><p>Original teaching content and questions, aligned to AQA’s specification checked ${(l.widget.startsWith('photo-')||l.widget.startsWith('separatebio-')||l.widget.startsWith('medicine-')||l.widget.startsWith('infection-')||l.widget.startsWith('plant-')||l.widget.startsWith('health-')||['heart-lab','circulation-route','vessel-lab','blood-lab','lung-lab','food-tests','amylase-practical','digestive-enzymes','enzyme-conditions','bile-lab','organisation-levels','digestion-route','enzyme-fit','culture-lab','growth-lab','zone-lab','active-lab','transport-compare','osmosis-lab','osmosis-practical','diffusion-lab','surface-lab','exchange-lab','stem-lineage','stem-uses','special-cell','cell-fate','chromosome-map','cell-cycle'].includes(l.widget)||l.widget.startsWith('bio-')||l.widget.startsWith('cells-')||l.widget.startsWith('rates-')||l.widget.startsWith('kinetics-')||l.widget==='practical-rates'||l.widget.startsWith('equilibrium-')||l.widget.startsWith('catalog-'))?(l.widget.startsWith('photo-')||l.widget.startsWith('separatebio-')||l.widget.startsWith('medicine-')||l.widget.startsWith('infection-')||l.widget.startsWith('plant-')||l.widget.startsWith('health-')||['heart-lab','circulation-route','vessel-lab','blood-lab','lung-lab'].includes(l.widget)?'20':'19'):(l.widget.startsWith('aqueous-')||l.widget.startsWith('industry-')||l.widget.startsWith('energy-')||l.widget.startsWith('thermal-'))?'18':'16'} October 2026. Current topic: ${safe(topic().coverage)}. Additional unbuilt subjects remain planned. Progress and review dates are stored in this browser; accounts and cross-device sync are not available.</p>`);};
$('#reset').onclick=()=>state.subject==='maths'?mathsStudio().resetLesson():modal(`<h2>Reset this lesson?</h2><p>Clear activities and scores for “${safe(current().title)}” on this device. Other lesson progress and your subject choices stay saved.</p><button class="primary" id="confirmReset">Reset this lesson</button>`);document.addEventListener('click',e=>{if(e.target.id==='confirmReset'){delete state.lessons[state.lessonId];$('#modal').close();view='lesson';refresh();}});
refresh();
